<!doctype html><html><head><style>body{font-family:DejaVu Sans;font-size:12px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border-bottom:1px solid #ddd;padding:8px;text-align:left}.right{text-align:right}</style></head><body><h1>Invoice {{ $sale->invoice_number }}</h1><p>{{ $sale->customer_name }} · {{ $sale->sale_date->format('d M Y') }}</p><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th class="right">Subtotal</th></tr></thead><tbody>@foreach($sale->items as $item)<tr><td>{{ $item->product->name }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->selling_price,2) }}</td><td class="right">{{ number_format($item->subtotal,2) }}</td></tr>@endforeach</tbody></table><p class="right"><strong>Total: {{ number_format($sale->total_amount,2) }}</strong></p></body></html>
